"""Label Manager for extracting class-level and legacy method-level observations with SZZ provenance."""
from __future__ import annotations

import hashlib
import json
import re
from pathlib import Path
from typing import Any, Dict, List, Optional, Set, Tuple
import git

from services.analyzer.roslyn_client import RoslynClient
from database.repository import RepositoryDB
from utils.logger import setup_logger
from utils.source_classifier import is_production_csharp_file

logger = setup_logger("label_manager")

AUTO_GENERATED_MARKERS = (
    "<auto-generated",
    "// generated by ",
    "// this code was generated by a tool",
    "// <auto-generated/>",
)


def compute_source_fingerprints(source_code: str) -> Tuple[str, str]:
    """Compute exact normalized source SHA-256 and comment/whitespace-normalized structural SHA-256."""
    norm_lines = [ln.rstrip() for ln in source_code.replace("\r\n", "\n").replace("\r", "\n").splitlines()]
    normalized = "\n".join(norm_lines).strip()
    source_fp = hashlib.sha256(normalized.encode("utf-8", errors="replace")).hexdigest()

    # Strip block and line comments, then collapse whitespace to detect structural near-duplicates
    no_block_comments = re.sub(r"/\*.*?\*/", "", normalized, flags=re.DOTALL)
    no_line_comments = re.sub(r"//.*?$", "", no_block_comments, flags=re.MULTILINE)
    collapsed = re.sub(r"\s+", " ", no_line_comments).strip()
    structural_fp = hashlib.sha256(collapsed.encode("utf-8", errors="replace")).hexdigest()
    return source_fp, structural_fp


def is_generated_source_content(content: str) -> bool:
    """Inspect top lines for auto-generated tool headers."""
    head = "\n".join(content.splitlines()[:15]).lower()
    return any(marker in head for marker in AUTO_GENERATED_MARKERS)


def is_substantive_class(class_loc: Dict[str, Any]) -> bool:
    """Filter out empty shells, markers, and trivial non-behavioral type declarations."""
    metrics = class_loc.get("metrics") or {}
    class_loc_count = int(metrics.get("class_loc", 0) or 0)
    method_count = int(metrics.get("method_count", 0) or 0)
    ctor_count = int(metrics.get("constructor_count", 0) or 0)
    prop_count = int(metrics.get("property_count", 0) or 0)
    stmt_count = int(metrics.get("total_statement_count", 0) or 0)

    if class_loc_count < 5:
        return False
    if method_count + ctor_count == 0 and prop_count < 2:
        return False
    if method_count + ctor_count + prop_count == 0 and stmt_count == 0:
        return False
    src = class_loc.get("source_code") or ""
    if is_generated_source_content(src):
        return False
    return True


class LabelManager:
    """Extracts class-level and legacy method-level observations from Git revisions and manages defect labels."""

    def __init__(self, db: RepositoryDB, roslyn_client: Optional[RoslynClient] = None) -> None:
        self.db = db
        self.roslyn = roslyn_client or RoslynClient()

    def get_file_content_at_commit(self, repo: git.Repo, commit_sha: str, file_path: str) -> Optional[str]:
        """Retrieve source code of a file at a specific historical commit."""
        try:
            norm_path = file_path.replace("\\", "/")
            commit = repo.commit(commit_sha)
            blob = commit.tree / norm_path
            raw = blob.data_stream.read().decode("utf-8", errors="replace")
            return raw.replace("\r\n", "\n").replace("\r", "\n")
        except Exception as e:
            logger.debug(f"Could not read {file_path} at commit {commit_sha[:8]}: {e}")
            return None

    # ---------------------------------------------------------
    # Class-Level Observation Extraction (Primary Research Target)
    # ---------------------------------------------------------
    def create_class_observations_from_szz(
        self,
        repository_id: int,
        local_path: Path | str,
        max_traces: int = 500,
    ) -> List[Dict[str, Any]]:
        """Map SZZ line-level traces to enclosing C# classes and create Label 1 observations."""
        repo = git.Repo(local_path)
        szz_traces = self.db.list_szz_results(repository_id)[:max_traces]
        if not szz_traces:
            return []

        # Group traces by (fixing_commit_sha, file_path) so each file revision is parsed once
        grouped_traces: Dict[Tuple[str, str], List[Dict[str, Any]]] = {}
        commit_cache: Dict[str, Any] = {}
        for trace in szz_traces:
            fix_sha = trace["fixing_commit_sha"]
            file_path = trace["file_path"]
            deleted_line = trace["deleted_line_number"]
            if not deleted_line or not is_production_csharp_file(file_path):
                continue
            grouped_traces.setdefault((fix_sha, file_path), []).append(trace)

        batch_items: List[Dict[str, Any]] = []
        file_contexts: Dict[str, Dict[str, Any]] = {}

        for idx, ((fix_sha, file_path), traces) in enumerate(grouped_traces.items()):
            try:
                if fix_sha not in commit_cache:
                    commit_cache[fix_sha] = repo.commit(fix_sha)
                fix_commit = commit_cache[fix_sha]
            except Exception:
                continue

            if not fix_commit.parents:
                continue
            parent_sha = fix_commit.parents[0].hexsha

            pre_fix_code = self.get_file_content_at_commit(repo, parent_sha, file_path)
            if not pre_fix_code or is_generated_source_content(pre_fix_code):
                continue

            item_id = f"szz_{idx}"
            batch_items.append({"id": item_id, "code": pre_fix_code})
            file_contexts[item_id] = {
                "fix_sha": fix_sha,
                "fix_commit": fix_commit,
                "parent_sha": parent_sha,
                "file_path": file_path,
                "pre_fix_code": pre_fix_code,
                "traces": traces,
            }

        if not batch_items:
            return []

        analysis_map = self.roslyn.analyze_batch(batch_items)

        # Aggregate blamed lines hitting the same class within a (parent_sha, file_path, qualified_class_name)
        class_aggregations: Dict[Tuple[str, str, str], Dict[str, Any]] = {}

        for item_id, ctx in file_contexts.items():
            resp = analysis_map.get(item_id)
            if not resp or not resp.get("success"):
                continue

            classes = resp.get("classes", [])
            if not classes:
                continue

            file_meta = resp.get("file_metadata") or {}
            pre_fp = hashlib.sha256(ctx["pre_fix_code"].encode("utf-8", errors="replace")).hexdigest()
            file_obs_id = self.db.insert_file_observation({
                "repository_id": repository_id,
                "commit_sha": ctx["parent_sha"],
                "file_path": ctx["file_path"],
                "total_lines": file_meta.get("total_lines", len(ctx["pre_fix_code"].splitlines())),
                "namespace_count": file_meta.get("namespace_count", 0),
                "class_count": file_meta.get("class_count", len(classes)),
                "method_count": file_meta.get("method_count", 0),
                "file_fingerprint": pre_fp,
            })

            for trace in ctx["traces"]:
                del_line = int(trace["deleted_line_number"])
                matching = [
                    c for c in classes
                    if c.get("start_line", 0) <= del_line <= c.get("end_line", 0)
                ]
                if not matching:
                    continue
                # Pick innermost class enclosing the deleted line
                matching.sort(key=lambda c: (c.get("end_line", 0) - c.get("start_line", 0), c.get("start_line", 0)))
                target_cls = matching[0]
                if not is_substantive_class(target_cls):
                    continue

                qname = target_cls.get("qualified_class_name") or target_cls.get("class_name", "UnknownClass")
                agg_key = (ctx["parent_sha"], ctx["file_path"], qname)

                if agg_key not in class_aggregations:
                    class_aggregations[agg_key] = {
                        "file_observation_id": file_obs_id,
                        "fix_sha": ctx["fix_sha"],
                        "fix_commit": ctx["fix_commit"],
                        "parent_sha": ctx["parent_sha"],
                        "file_path": ctx["file_path"],
                        "cls": target_cls,
                        "bics": set(),
                        "lines": [],
                        "confidences": [],
                    }
                agg = class_aggregations[agg_key]
                agg["bics"].add(trace["inducing_commit_sha"])
                agg["lines"].append(del_line)
                agg["confidences"].append(float(trace.get("confidence", 0.85)))

        # Batch-analyze all post-fix revisions in one Roslyn process for corrected_code capture
        post_fix_batch_items: List[Dict[str, Any]] = []
        seen_post_keys: Set[Tuple[str, str]] = set()
        for agg in class_aggregations.values():
            post_key = (agg["fix_sha"], agg["file_path"])
            if post_key not in seen_post_keys:
                seen_post_keys.add(post_key)
                post_code = self.get_file_content_at_commit(repo, agg["fix_sha"], agg["file_path"])
                if post_code:
                    post_fix_batch_items.append({
                        "id": f"{agg['fix_sha']}|{agg['file_path']}",
                        "code": post_code,
                    })

        post_batch_results = self.roslyn.analyze_batch(post_fix_batch_items) if post_fix_batch_items else {}
        post_fix_cache: Dict[Tuple[str, str], List[Dict[str, Any]]] = {}
        for agg in class_aggregations.values():
            post_key = (agg["fix_sha"], agg["file_path"])
            if post_key not in post_fix_cache:
                resp = post_batch_results.get(f"{agg['fix_sha']}|{agg['file_path']}")
                post_fix_cache[post_key] = resp.get("classes", []) if (resp and resp.get("success")) else []

        created_observations: List[Dict[str, Any]] = []

        for _, agg in class_aggregations.items():
            cls = agg["cls"]
            fix_sha = agg["fix_sha"]
            file_path = agg["file_path"]
            qname = cls.get("qualified_class_name") or cls.get("class_name")

            post_key = (fix_sha, file_path)
            corrected_source: Optional[str] = None
            for pc in post_fix_cache.get(post_key, []):
                if (pc.get("qualified_class_name") == qname) or (pc.get("class_name") == cls.get("class_name")):
                    corrected_source = pc.get("source_code")
                    break

            src_code = cls.get("source_code", "")
            src_fp, struct_fp = compute_source_fingerprints(src_code)
            bics_sorted = sorted(agg["bics"])
            lines_sorted = sorted(set(agg["lines"]))

            obs_data = {
                "file_observation_id": agg["file_observation_id"],
                "repository_id": repository_id,
                "commit_sha": agg["parent_sha"],
                "parent_sha": bics_sorted[0] if bics_sorted else None,
                "bug_fix_commit_sha": fix_sha,
                "bug_inducing_commit_sha": ",".join(bics_sorted[:5]),
                "file_path": file_path,
                "namespace_name": cls.get("namespace_name", "Global"),
                "class_name": cls.get("class_name", "UnknownClass"),
                "qualified_class_name": qname,
                "type_kind": cls.get("type_kind", "class"),
                "start_line": cls.get("start_line", 1),
                "end_line": cls.get("end_line", 1),
                "is_nested": bool(cls.get("is_nested", False)),
                "enclosing_type_name": cls.get("enclosing_type_name"),
                "source_code": src_code,
                "corrected_code": corrected_source,
                "source_fingerprint": src_fp,
                "structural_fingerprint": struct_fp,
                "label": 1,
                "label_confidence": round(max(agg["confidences"]), 3),
                "szz_trace_count": len(lines_sorted),
                "blamed_lines_json": json.dumps(lines_sorted),
                "evidence_category": "szz_class_bic",
                "bug_fixing_commit_message": agg["fix_commit"].message.strip()[:500],
                "issue_or_pr_url": None,
            }
            obs_id = self.db.insert_class_observation(obs_data)
            obs_data["id"] = obs_id

            metrics = cls.get("metrics") or {}
            if obs_id > 0 and metrics:
                feat_payload = dict(metrics)
                feat_payload.update({
                    "class_observation_id": obs_id,
                    "feature_schema_version": self.roslyn.FEATURE_SCHEMA_VERSION,
                    "analyzer_version": self.roslyn.ANALYZER_VERSION,
                    "status": "success",
                    "raw_metrics_json": json.dumps(metrics),
                })
                self.db.upsert_class_features(feat_payload)

            created_observations.append(obs_data)

        logger.info(f"Created {len(created_observations)} Label 1 class observations from SZZ traces for repo #{repository_id}.")
        return created_observations

    def sample_candidate_clean_classes(
        self,
        repository_id: int,
        local_path: Path | str,
        target_count: int = 30,
        candidate_file_limit: int = 120,
    ) -> List[Dict[str, Any]]:
        """Sample candidate-clean (Label 0) production C# classes from HEAD with zero bug-fix history."""
        repo = git.Repo(local_path)
        head_commit = repo.head.commit.hexsha

        existing_buggy = self.db.list_class_observations(repository_id=repository_id, label=1)
        known_buggy_classes: Set[str] = {
            f"{o['file_path']}:{o['qualified_class_name']}" for o in existing_buggy
        }
        known_buggy_fps: Set[str] = {o["source_fingerprint"] for o in existing_buggy}
        touched_bug_files = {
            p.replace("\\", "/") for p in self.db.get_bug_fix_touched_files(repository_id)
        }

        all_prod_files = [
            f for f in repo.git.ls_files().splitlines()
            if is_production_csharp_file(f) and f.replace("\\", "/") not in touched_bug_files
        ]
        self.db.update_repository_metrics(repository_id, {"production_cs_files_count": len(all_prod_files) + len(touched_bug_files)})

        if not all_prod_files:
            return []

        # Spread selection across repository files deterministically
        if len(all_prod_files) > candidate_file_limit:
            step = len(all_prod_files) / candidate_file_limit
            sampled_files = [all_prod_files[int(i * step)] for i in range(candidate_file_limit)]
        else:
            sampled_files = all_prod_files

        batch_items: List[Dict[str, Any]] = []
        file_contents: Dict[str, Tuple[str, str]] = {}
        for idx, fpath in enumerate(sampled_files):
            content = self.get_file_content_at_commit(repo, head_commit, fpath)
            if not content or is_generated_source_content(content):
                continue
            item_id = f"clean_{idx}"
            batch_items.append({"id": item_id, "code": content})
            file_contents[item_id] = (fpath, content)

        if not batch_items:
            return []

        analysis_map = self.roslyn.analyze_batch(batch_items)
        clean_observations: List[Dict[str, Any]] = []
        seen_clean_fps: Set[str] = set()

        for item_id, (fpath, content) in file_contents.items():
            if len(clean_observations) >= target_count:
                break
            resp = analysis_map.get(item_id)
            if not resp or not resp.get("success"):
                continue

            classes = resp.get("classes", [])
            substantive_classes = [c for c in classes if is_substantive_class(c)]
            if not substantive_classes:
                continue

            file_meta = resp.get("file_metadata") or {}
            file_fp = hashlib.sha256(content.encode("utf-8", errors="replace")).hexdigest()
            file_obs_id = self.db.insert_file_observation({
                "repository_id": repository_id,
                "commit_sha": head_commit,
                "file_path": fpath,
                "total_lines": file_meta.get("total_lines", len(content.splitlines())),
                "namespace_count": file_meta.get("namespace_count", 0),
                "class_count": file_meta.get("class_count", len(classes)),
                "method_count": file_meta.get("method_count", 0),
                "file_fingerprint": file_fp,
            })

            for cls in substantive_classes:
                if len(clean_observations) >= target_count:
                    break
                qname = cls.get("qualified_class_name") or cls.get("class_name", "UnknownClass")
                if f"{fpath}:{qname}" in known_buggy_classes:
                    continue

                src_code = cls.get("source_code", "")
                src_fp, struct_fp = compute_source_fingerprints(src_code)
                if src_fp in known_buggy_fps or src_fp in seen_clean_fps:
                    continue
                seen_clean_fps.add(src_fp)

                obs_data = {
                    "file_observation_id": file_obs_id,
                    "repository_id": repository_id,
                    "commit_sha": head_commit,
                    "parent_sha": None,
                    "bug_fix_commit_sha": None,
                    "bug_inducing_commit_sha": None,
                    "file_path": fpath,
                    "namespace_name": cls.get("namespace_name", "Global"),
                    "class_name": cls.get("class_name", "UnknownClass"),
                    "qualified_class_name": qname,
                    "type_kind": cls.get("type_kind", "class"),
                    "start_line": cls.get("start_line", 1),
                    "end_line": cls.get("end_line", 1),
                    "is_nested": bool(cls.get("is_nested", False)),
                    "enclosing_type_name": cls.get("enclosing_type_name"),
                    "source_code": src_code,
                    "corrected_code": None,
                    "source_fingerprint": src_fp,
                    "structural_fingerprint": struct_fp,
                    "label": 0,
                    "label_confidence": 0.80,
                    "szz_trace_count": 0,
                    "blamed_lines_json": json.dumps([]),
                    "evidence_category": "stable_head_class",
                    "bug_fixing_commit_message": "Sampled from stable HEAD file without recorded bug-fix traces.",
                    "issue_or_pr_url": None,
                }
                obs_id = self.db.insert_class_observation(obs_data)
                obs_data["id"] = obs_id

                metrics = cls.get("metrics") or {}
                if obs_id > 0 and metrics:
                    feat_payload = dict(metrics)
                    feat_payload.update({
                        "class_observation_id": obs_id,
                        "feature_schema_version": self.roslyn.FEATURE_SCHEMA_VERSION,
                        "analyzer_version": self.roslyn.ANALYZER_VERSION,
                        "status": "success",
                        "raw_metrics_json": json.dumps(metrics),
                    })
                    self.db.upsert_class_features(feat_payload)

                clean_observations.append(obs_data)

        logger.info(f"Sampled {len(clean_observations)} candidate-clean (Label 0) classes for repo #{repository_id}.")
        return clean_observations

    def mark_class_observation_uncertain(self, class_observation_id: int, reason: str = "ambiguous_evidence") -> None:
        self.db.update_class_observation_label(class_observation_id, new_label=-1, reason=reason)

    # ---------------------------------------------------------
    # Historical Method-Level Extraction (Preserved)
    # ---------------------------------------------------------
    def create_observations_from_szz(
        self,
        repository_id: int,
        local_path: Path | str,
    ) -> List[Dict[str, Any]]:
        """Map SZZ line-level traces to enclosing C# methods and create Label 1 (Buggy) observations."""
        repo = git.Repo(local_path)
        szz_traces = self.db.list_szz_results(repository_id)

        created_observations: List[Dict[str, Any]] = []
        processed_keys: Set[str] = set()

        for trace in szz_traces:
            fix_sha = trace["fixing_commit_sha"]
            bic_sha = trace["inducing_commit_sha"]
            file_path = trace["file_path"]
            deleted_line = trace["deleted_line_number"]

            if not deleted_line or not is_production_csharp_file(file_path):
                continue

            fix_commit = repo.commit(fix_sha)
            if not fix_commit.parents:
                continue
            parent_sha = fix_commit.parents[0].hexsha

            pre_fix_code = self.get_file_content_at_commit(repo, parent_sha, file_path)
            if not pre_fix_code:
                continue

            pre_method = self.roslyn.find_enclosing_method(pre_fix_code, deleted_line)
            if not pre_method:
                continue

            dedup_key = f"{parent_sha}:{file_path}:{pre_method['method_signature']}"
            if dedup_key in processed_keys:
                continue
            processed_keys.add(dedup_key)

            post_fix_code = self.get_file_content_at_commit(repo, fix_sha, file_path)
            corrected_source: Optional[str] = None
            if post_fix_code:
                post_methods = self.roslyn.extract_methods(code=post_fix_code)
                for pm in post_methods:
                    if pm["method_name"] == pre_method["method_name"] and pm["class_name"] == pre_method["class_name"]:
                        corrected_source = pm["source_code"]
                        break

            obs_data = {
                "repository_id": repository_id,
                "commit_sha": parent_sha,
                "parent_sha": bic_sha,
                "bug_fix_commit_sha": fix_sha,
                "file_path": file_path,
                "class_name": pre_method["class_name"],
                "method_name": pre_method["method_name"],
                "method_signature": pre_method["method_signature"],
                "source_code": pre_method["source_code"],
                "corrected_code": corrected_source,
                "label": 1,
                "label_confidence": trace.get("confidence", 0.85),
                "evidence_category": "szz_bic",
                "bug_fixing_commit_message": fix_commit.message.strip(),
                "issue_or_pr_url": None,
            }
            obs_id = self.db.insert_observation(obs_data)
            obs_data["id"] = obs_id
            created_observations.append(obs_data)

        logger.info(f"Created {len(created_observations)} Label 1 observations from SZZ traces for repo #{repository_id}.")
        return created_observations

    def sample_candidate_clean_methods(
        self,
        repository_id: int,
        local_path: Path | str,
        target_count: int = 50,
    ) -> List[Dict[str, Any]]:
        """Sample candidate non-buggy (Label 0) methods from stable repository revisions."""
        repo = git.Repo(local_path)
        head_commit = repo.head.commit.hexsha

        known_buggy_signatures = {
            f"{o['file_path']}:{o['method_signature']}"
            for o in self.db.list_observations(repository_id=repository_id, label=1)
        }

        cs_files = [f for f in repo.git.ls_files().splitlines() if is_production_csharp_file(f)]
        clean_observations: List[Dict[str, Any]] = []

        for fpath in cs_files:
            if len(clean_observations) >= target_count:
                break

            content = self.get_file_content_at_commit(repo, head_commit, fpath)
            if not content:
                continue

            methods = self.roslyn.extract_methods(code=content)
            for m in methods:
                sig_key = f"{fpath}:{m['method_signature']}"
                if sig_key in known_buggy_signatures:
                    continue

                obs_data = {
                    "repository_id": repository_id,
                    "commit_sha": head_commit,
                    "parent_sha": None,
                    "bug_fix_commit_sha": None,
                    "file_path": fpath,
                    "class_name": m["class_name"],
                    "method_name": m["method_name"],
                    "method_signature": m["method_signature"],
                    "source_code": m["source_code"],
                    "corrected_code": None,
                    "label": 0,
                    "label_confidence": 0.80,
                    "evidence_category": "stable_version",
                    "bug_fixing_commit_message": "Sampled from stable HEAD without known defect traces.",
                    "issue_or_pr_url": None,
                }
                obs_id = self.db.insert_observation(obs_data)
                obs_data["id"] = obs_id
                clean_observations.append(obs_data)

                if len(clean_observations) >= target_count:
                    break

        logger.info(f"Sampled {len(clean_observations)} candidate clean (Label 0) methods for repo #{repository_id}.")
        return clean_observations

    def mark_observation_uncertain(self, observation_id: int, reason: str = "ambiguous_evidence") -> None:
        """Mark an observation as uncertain (-1) so it is excluded from training."""
        self.db.update_observation_label(observation_id, new_label=-1, reason=reason)
